INSERT INTO shopitems (shopid, itemid, price, pitch, position)
WITH RECURSIVE scroll_ranges (start_itemid, end_itemid) AS (
    SELECT 2040000, 2040031
    UNION ALL SELECT 2040041, 2040046
    UNION ALL SELECT 2040100, 2040119
    UNION ALL SELECT 2040200, 2040209
    UNION ALL SELECT 2040300, 2040331
    UNION ALL SELECT 2040333, 2040340
    UNION ALL SELECT 2040400, 2040427
    UNION ALL SELECT 2040429, 2040436
    UNION ALL SELECT 2040500, 2040534
    UNION ALL SELECT 2040538, 2040543
    UNION ALL SELECT 2040600, 2040627
    UNION ALL SELECT 2040629, 2040636
    UNION ALL SELECT 2040700, 2040723
    UNION ALL SELECT 2040727, 2040742
    UNION ALL SELECT 2040755, 2040760
    UNION ALL SELECT 2040800, 2040826
    UNION ALL SELECT 2040829, 2040834
    UNION ALL SELECT 2040900, 2040912
    UNION ALL SELECT 2040914, 2040933
    UNION ALL SELECT 2040936, 2040943
    UNION ALL SELECT 2041000, 2041062
    UNION ALL SELECT 2041066, 2041069
    UNION ALL SELECT 2041100, 2041119
    UNION ALL SELECT 2041200, 2041200
    UNION ALL SELECT 2041211, 2041212
    UNION ALL SELECT 2041300, 2041319
    UNION ALL SELECT 2043000, 2043013
    UNION ALL SELECT 2043015, 2043019
    UNION ALL SELECT 2043021, 2043025
    UNION ALL SELECT 2043100, 2043108
    UNION ALL SELECT 2043110, 2043114
    UNION ALL SELECT 2043116, 2043120
    UNION ALL SELECT 2043200, 2043208
    UNION ALL SELECT 2043210, 2043214
    UNION ALL SELECT 2043216, 2043220
    UNION ALL SELECT 2043300, 2043308
    UNION ALL SELECT 2043311, 2043313
    UNION ALL SELECT 2043700, 2043708
    UNION ALL SELECT 2043711, 2043713
    UNION ALL SELECT 2043800, 2043808
    UNION ALL SELECT 2043811, 2043813
    UNION ALL SELECT 2044000, 2044008
    UNION ALL SELECT 2044010, 2044015
    UNION ALL SELECT 2044024, 2044028
    UNION ALL SELECT 2044100, 2044108
    UNION ALL SELECT 2044110, 2044114
    UNION ALL SELECT 2044116, 2044120
    UNION ALL SELECT 2044200, 2044208
    UNION ALL SELECT 2044210, 2044214
    UNION ALL SELECT 2044216, 2044220
    UNION ALL SELECT 2044300, 2044308
    UNION ALL SELECT 2044310, 2044314
    UNION ALL SELECT 2044316, 2044320
