    UNION ALL SELECT 2044711, 2044713
    UNION ALL SELECT 2044800, 2044817
    UNION ALL SELECT 2044900, 2044910
    UNION ALL SELECT 2048000, 2048013
    UNION ALL SELECT 2049000, 2049003
    UNION ALL SELECT 2049100, 2049110
    UNION ALL SELECT 2049112, 2049114
    UNION ALL SELECT 2049200, 2049211
),
scrolls (itemid, end_itemid) AS (
    SELECT start_itemid, end_itemid
    FROM scroll_ranges
    UNION ALL
    SELECT itemid + 1, end_itemid
    FROM scrolls
    WHERE itemid < end_itemid
),
missing_scrolls AS (
    SELECT itemid,
           ROW_NUMBER() OVER (ORDER BY itemid) AS sort_order
    FROM scrolls
    WHERE itemid NOT IN (
        2040000, 2040003, 2040006, 2040007, 2040018, 2040024, 2040027, 2040041,
        2040042, 2040102, 2040107, 2040202, 2040207, 2040300, 2040303, 2040312,
        2040316, 2040319, 2040324, 2040334, 2040400, 2040403, 2040414, 2040417,
        2040420, 2040423, 2040430, 2040500, 2040503, 2040506, 2040507, 2040512,
        2040515, 2040530, 2040538, 2040539, 2040600, 2040603, 2040614, 2040617,
        2040620, 2040623, 2040630, 2040700, 2040703, 2040706, 2040709, 2040710,
        2040711, 2040740, 2040741, 2040742, 2040758, 2040800, 2040803, 2040806,
        2040807, 2040818, 2040823, 2040829, 2040830, 2040900, 2040903, 2040918,
        2040923, 2040926, 2040929, 2040936, 2041000, 2041003, 2041006, 2041009,
        2041012, 2041015, 2041018, 2041021, 2041024, 2041025, 2041066, 2041067,
        2041100, 2041103, 2041106, 2041109, 2041200, 2041300, 2041303, 2041306,
        2041309, 2043000, 2043003, 2043010, 2043015, 2043023, 2043100, 2043103,
        2043110, 2043117, 2043200, 2043203, 2043210, 2043217, 2043300, 2043303,
        2043312, 2043700, 2043703, 2043712, 2043800, 2043803, 2043812, 2044000,
        2044003, 2044010, 2044025, 2044100, 2044103, 2044110, 2044117, 2044200,
        2044203, 2044210, 2044217, 2044300, 2044303, 2044310, 2044317, 2044400,
        2044403, 2044410, 2044417, 2044500, 2044503, 2044512, 2044600, 2044603,
        2044612, 2044700, 2044703, 2044712, 2044800, 2044805, 2044815, 2044900,
        2044908, 2048000, 2048003, 2049101, 2049102, 2049103, 2049104, 2049112,
        2049113, 2049114
    )
      AND NOT EXISTS (
        SELECT 1
        FROM shopitems existing
        WHERE existing.shopid = 9900001
          AND existing.itemid = scrolls.itemid
    )
),
base AS (
    SELECT COALESCE(MAX(position), 0) AS max_position
    FROM shopitems
    WHERE shopid = 9900001
)
SELECT 9900001,
       missing_scrolls.itemid,
       6666,
       0,
       base.max_position + missing_scrolls.sort_order
FROM missing_scrolls
CROSS JOIN base;
